import { insideBox, boxDetails } from './box-details.js';
import { deliveryTrackingUrl } from '../delivery-tracking.js';
import { sortProducts, productCategoryIds } from '../admin/catalog-ordering.js';
import {fulfillmentStatus} from '../admin/refund-status.js';
import {mountCustomerCalendar} from './customer-calendar.js';
import {syncCheckoutFields,socialContactMessage} from '../admin/checkout-fields.js';
import {visibleProductLabel} from '../admin/product-label.js';
import {api,auth,ready,configured,money,escapeHtml as esc,formatDate,toast,upload} from '../admin/client.js';
import {dateInManila,addDays,availability,selectionPrice,selectionLabels,earliestLeadDate,deliveryRestriction,deliveryZone,customerBookingWindow,customerDateIssue,allowsSameDay,sameDayBasketEligible,basketStockIssues,firstAvailableDate,prepareCatalog,flavorStock} from './shop-rules.js';
const $=s=>document.querySelector(s), app=$('#app');
const demo=false;
const storageKey='elio-checkout-v1';
let state={items:[],fulfillment_date:'',method:'pickup',buyer:{},recipient:{},address:{},instructions:'',promo_code:'',idempotency_key:crypto.randomUUID()};
try{const saved=JSON.parse(sessionStorage.getItem(storageKey)||'null');if(saved&&Date.now()-saved.saved_at<86400000&&Array.isArray(saved.items))state={...state,...saved}}catch{}
state.method='pickup';state.fulfillment_date='';
let catalog={products:[],categories:[],settings:{},zones:[],inventory:[]},category='all',query='',session=null,quote=null,busy=false,refreshTimer=null,customerCalendar=null;
let promoRequest=0,promoPending=false,promoQuote=null,promoKey='',promoMessage='',promoTone='';
const persist=()=>{try{sessionStorage.setItem(storageKey,JSON.stringify({...state,saved_at:Date.now()}))}catch{}};
const labelsText=labels=>(labels||[]).map(l=>typeof l==='string'?l:`${l.quantity} × ${l.label}${l.surcharge_cents ? ` (+${money(l.surcharge_cents)} each; ${money(l.surcharge_cents*l.quantity)} per unit)` : ''}`).join(', ');
const statusLabel=s=>(s||'').replaceAll('_',' ').replace(/^./,c=>c.toUpperCase());
const safeImage=url=>{try{const u=new URL(url,location.href);return ['https:','http:'].includes(u.protocol)?esc(u.href):''}catch{return ''}};
const datetime=d=>d?new Intl.DateTimeFormat('en-PH',{timeZone:'Asia/Manila',dateStyle:'medium',timeStyle:'short'}).format(new Date(d))+' PHT':'—';
const icon='<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M5 8h14l-1 12H6L5 8Z"/><path d="M9 9V6a3 3 0 0 1 6 0v3"/></svg>';
function lineProduct(line){return catalog.products.find(p=>p.id===line.product_id)}
function orderItem(line){
 const photo=[line.photo_url,lineProduct(line)?.photos?.[0]].filter(value=>typeof value==='string'&&value.trim()).map(safeImage).find(Boolean)||'';
 const flavors=labelsText(line.selection_labels?.length?line.selection_labels:(line.flavor_contents||[]).map(f=>({label:f.name,quantity:f.quantity})));
 return `<div class="cart-line order-product"><div class="order-product-thumbnail" aria-hidden="true"><span>ELIO</span>${photo?`<img src="${photo}" alt="" width="88" height="88" loading="lazy" decoding="async">`:''}</div><div class="order-product-details"><h3>${line.quantity} × ${esc(line.name)}</h3><div class="cart-options">${esc(flavors)}</div><small class="muted">${money(line.unit_price_cents)} each</small></div><strong class="order-product-total">${money(line.line_total_cents??line.quantity*line.unit_price_cents)}</strong></div>`;
}
function orderTracking(order){
 if(order.method!=='delivery'||fulfillmentStatus(order)==='refunded'||['cancelled','expired'].includes(order.fulfillment_status))return '';
 const link=deliveryTrackingUrl(order.delivery_tracking_url);
 if(!link&&!order.delivery_tracking_updated_at)return '';
 return `<section class="panel order-section delivery-tracking"><h2>Delivery tracking</h2>${link?`<p class="muted">Follow your rider’s progress using the latest link from our kitchen.</p><a class="button block" href="${esc(link)}" target="_blank" rel="noopener noreferrer">Track your delivery ↗</a>`:'<p class="muted">Tracking is temporarily unavailable. We’ll email you when a new tracking link is ready.</p>'}${order.delivery_tracking_updated_at?`<small class="muted">Updated ${datetime(order.delivery_tracking_updated_at)}</small>`:''}</section>`;
}
function linePrice(line){try{return selectionPrice(lineProduct(line),line.selections||{})}catch{return Number(line.unit_price_cents||0)}}
function subtotal(){return state.items.reduce((sum,line)=>sum+linePrice(line)*line.quantity,0)}
function amountLines(q){const s=q||{subtotal_cents:subtotal(),discount_cents:0,delivery_cents:zoneFee(),total_cents:subtotal()+zoneFee()};return `<div class="totals"><div><span>Products</span><span>${money(s.subtotal_cents)}</span></div>${s.discount_cents?`<div><span>Promo discount</span><span>−${money(s.discount_cents)}</span></div>`:''}<div><span>${state.method==='pickup'?'Pickup':'Delivery'}</span><span>${state.method==='pickup'?'Free':state.address.locality?money(s.delivery_cents):'Choose area'}</span></div><div class="grand-total"><span>Total</span><span>${money(s.total_cents)}</span></div></div>`}
function selectedZone(){return deliveryZone(catalog.zones,state.address.locality,state.method)}
function zoneFee(){return Number(selectedZone()?.fee_cents||0)}
function zoneDescription(description){return typeof description==='string'&&description.trim()?`<div class="help-card delivery-zone-note"><strong>Delivery area information</strong><div class="delivery-zone-text">${esc(description)}</div></div>`:''}
function updateZoneDescription(){const el=$('#delivery-zone-description');if(el)el.innerHTML=zoneDescription(selectedZone()?.description)}
function sameDayEligible(){return sameDayBasketEligible(state.items,catalog.products,catalog.inventory,state.method)}
function updateFulfillment(){
  const reason=deliveryRestriction(state.items,catalog.products,state.fulfillment_date,catalog.settings),button=$('[data-method="delivery"]'),notice=$('#fulfillment-notice');
  if(button){button.disabled=!!reason;button.setAttribute('aria-describedby','fulfillment-notice')}
  if(notice){notice.textContent=customerDateIssue(state.fulfillment_date,catalog.settings,state.method,new Date(),sameDayEligible())||reason;notice.hidden=!notice.textContent}
}
function issues(){return [...basketStockIssues(state.items,catalog.products,catalog.inventory,state.fulfillment_date),...state.items.flatMap(line=>{const p=lineProduct(line);if(!p)return [`${line.name||'An item'} is no longer available. Remove it to continue.`];const a=displayAvailability(p);const totalQty=state.items.filter(l=>l.product_id===p.id).reduce((s,l)=>s+l.quantity,0);let issues=[];if(!a.available)issues.push(`${p.name}: ${a.reason}`);else if(totalQty<p.min_quantity)issues.push(`${p.name}: add at least ${p.min_quantity} units across your selected configurations.`);else if(state.fulfillment_date&&totalQty>a.remaining)issues.push(`${p.name}: only ${a.remaining} available on this date.`);try{selectionPrice(p,line.selections)}catch(e){issues.push(`${p.name}: ${e.message}`)}return issues})]}
function displayAvailability(p){
 const result=availability(p,state.fulfillment_date,catalog.settings,catalog.inventory,new Date(),state.method);
 if(!state.fulfillment_date&&!firstAvailableDate([], [p], catalog.settings, catalog.inventory))return {...result,available:false,reason:'No available dates yet'};
 return result;
}
function earliestFor(p){if(state.method==='delivery'&&p.pickup_only===true)return 'Pickup only';const lead=earliestLeadDate(p,catalog.settings);if(!lead)return 'No production days configured';if(lead>customerBookingWindow().maxDate)return 'Outside the current booking window';for(let date=lead;date<=customerBookingWindow().maxDate;date=addDays(date,1)){if(availability(p,date,catalog.settings,catalog.inventory,new Date(),state.method).available)return formatDate(date)}return 'No available dates in the current booking window'}
function productLabelBadge(value){const label=visibleProductLabel(value);return label?`<span class="badge product-label" style="background-color:${label.color};color:${label.textColor}">${esc(label.text)}</span>`:''}
function productCard(p){
 const a=displayAvailability(p);
 return `<button type="button" class="elio-product-card" data-product="${esc(p.id)}" aria-label="${p.kind==='custom_box'?'Customize':'View'} ${esc(p.name)}" aria-haspopup="dialog"><div class="elio-product-media">${p.photos?.length?'<img src="'+safeImage(p.photos[0])+'" alt="" loading="lazy">':placeholder()}${productLabelBadge(p.label)}</div><div class="elio-product-copy"><h3>${esc(p.name)}</h3><p class="elio-product-description">${esc(p.description||'')}</p><div class="elio-product-bottom"><strong>${p.kind==='custom_box'?'From ':''}${money(p.price_cents)}</strong><span class="elio-product-add" aria-hidden="true">+</span></div><p class="availability ${a.available?'':'unavailable'}">${esc(a.reason)}</p></div></button>`;
}
function placeholder(){return '<div class="empty-state" aria-label="Product photo coming soon"><div class="empty-icon">'+icon+'</div><small>Fresh from our kitchen</small></div>'}
function renderShop(){
  clearTimeout(refreshTimer);customerCalendar?.destroy();customerCalendar=null;
  document.body.classList.remove('viewing-order');
  app.innerHTML=`${catalog.settings.paused?'<div class="notice" role="status">'+esc(catalog.settings.pause_message||'We’re temporarily pausing new orders. Please check back soon.')+'</div>':''}
  <section class="fulfillment-bar" aria-label="Choose fulfillment"><div class="date-field"><span id="fulfillment-date-label">When is your Elio day?</span><div id="customer-date-picker"></div></div><div class="method-toggle" role="group" aria-label="Pickup or delivery"><button data-method="pickup" class="${state.method==='pickup'?'selected':''}" aria-pressed="${state.method==='pickup'}">Pickup</button><button data-method="delivery" class="${state.method==='delivery'?'selected':''}" aria-pressed="${state.method==='delivery'}">Delivery</button></div></section><div id="fulfillment-notice" class="notice" role="status" hidden></div>
  <div class="shop-layout"><section id="cheesecake-boxes"><div class="section-heading"><h2>Our Cheesecake Boxes</h2><span class="muted">A box for every craving.</span></div><div id="product-grid" class="product-grid"></div><p class="help-card">One basket, one date. Fixed sets come as shown; build your own box to choose your three flavors.</p></section><aside id="cart" class="panel cart-panel" aria-label="Your basket"></aside></div><button id="mobile-cart" class="mobile-cart" hidden></button>`;
  renderProducts();renderCart();
  customerCalendar=mountCustomerCalendar($('#customer-date-picker'),{value:state.fulfillment_date,settings:catalog.settings,method:state.method,allowSameDay:sameDayEligible(),onSelect:date=>{state.fulfillment_date=date;quote=null;persist();renderProducts();renderCart();if(configured)loadInventory()}});
  document.querySelectorAll('[data-method]').forEach(b=>b.onclick=()=>{state.method=b.dataset.method;quote=null;persist();renderShop()});
}
function renderProducts(){
 const grid=$('#product-grid');if(!grid)return;
 const categories=(catalog.categories||[]).filter(c=>c.scope==='boxes'&&catalog.products.some(p=>productCategoryIds(p,catalog.categories).includes(c.id))).sort((a,b)=>a.sort_order-b.sort_order||a.name.localeCompare(b.name));
 if(category!=='all'&&!categories.some(c=>c.id===category))category='all';
 let filters=$('#box-category-filters');if(!filters){filters=document.createElement('div');filters.id='box-category-filters';filters.className='box-category-filters';grid.before(filters);}
 filters.hidden=!categories.length;
 filters.innerHTML=[{id:'all',name:'All boxes'},...categories].map(c=>`<button type="button" data-box-category="${esc(c.id)}" aria-pressed="${category===c.id}">${esc(c.name)}</button>`).join('');
 filters.querySelectorAll('button').forEach(button=>button.onclick=()=>{category=button.dataset.boxCategory;renderProducts();filters.querySelector(`[data-box-category="${CSS.escape(category)}"]`)?.focus({preventScroll:true});});
 const products=sortProducts(catalog.products,category==='all'?'':category).filter(p=>category==='all'||productCategoryIds(p,catalog.categories).includes(category));
 grid.innerHTML=products.length?products.map(p=>productCard(p)).join(''):'<div class="empty-state"><h3>No boxes are listed right now.</h3><p>Please check back soon.</p></div>';
 grid.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>openProduct(b.dataset.product));
}

function renderCart(){customerCalendar?.update({value:state.fulfillment_date,settings:catalog.settings,method:state.method,allowSameDay:sameDayEligible()});updateFulfillment();const count=state.items.reduce((s,l)=>s+l.quantity,0),errors=issues();$('#cart').innerHTML=`<div class="cart-head"><h2 class="no-margin">Your basket</h2><span class="cart-count">${count}</span></div>${!count?`<div class="empty-state"><div class="empty-icon">${icon}</div><h3>A little room for something sweet</h3><p style="font-size:11px">Pick a treat from the menu<br>and make it yours.</p></div>`:state.items.map((line,i)=>`<div class="cart-line"><div><h3>${esc(lineProduct(line)?.name||line.name||'Unavailable item')}</h3>${lineProduct(line)?.pickup_only===true?'<span class="badge pickup-only-badge">Pickup only</span>':''}<div class="cart-options">${esc(lineProduct(line)?selectionLabels(lineProduct(line),line.selections).join('\n'):'Please remove this item.')}</div><div style="margin-top:9px"><div class="quantity-control"><button data-qty="${i}" data-delta="-1" ${line.quantity<=1?'disabled':''} aria-label="Decrease ${esc(line.name||'item')} quantity">−</button><span>${line.quantity}</span><button data-qty="${i}" data-delta="1" aria-label="Increase ${esc(line.name||'item')} quantity">+</button></div><button data-remove="${i}" class="remove-line">Remove</button></div></div><span class="line-price">${money(linePrice(line)*line.quantity)}</span></div>`).join('')}
  ${errors.length?`<div class="notice danger" style="margin-top:16px">${[...new Set(errors)].map(esc).join('<br>')}</div>`:''}${count?amountLines():''}<button id="checkout-button" class="button block" ${!count||!state.fulfillment_date||catalog.settings.paused||errors.length||(!configured&&!demo)?'disabled':''}>${demo?'Preview checkout':'Continue to checkout'} <span aria-hidden="true">→</span></button><p class="cart-footnote">${count&&state.fulfillment_date?`${formatDate(state.fulfillment_date)} · ${statusLabel(state.method)}`:'Select your date before checkout'}<br>Full payment · Confirmed after manual review</p>`;
  document.querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>{const l=state.items[+b.dataset.qty],minimum=1;l.quantity=Math.max(minimum,l.quantity+Number(b.dataset.delta));quote=null;persist();renderCart()});
  document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{state.items.splice(+b.dataset.remove,1);quote=null;persist();renderCart()});
  $('#checkout-button').onclick=()=>{if(!state.fulfillment_date){$('.customer-calendar-trigger')?.focus();toast('Choose a fulfillment date to continue.');return}openCheckout()};
  const mobile=$('#mobile-cart');mobile.hidden=!count;mobile.innerHTML=`<span>${count} ${count===1?'treat':'treats'} · View basket</span><span>${money(subtotal())}</span>`;mobile.onclick=()=>$('#cart').scrollIntoView({behavior:'smooth',block:'start'});
}
async function loadInventory(){try{const next=await api('catalog',{fulfillment_date:state.fulfillment_date});catalog=prepareCatalog(next);customerCalendar?.update({value:state.fulfillment_date,settings:catalog.settings,method:state.method,allowSameDay:sameDayEligible()});renderProducts();renderCart()}catch(e){toast(e.message,'danger')}}
function openProduct(id){
  const p=catalog.products.find(p=>p.id===id),dialog=$('#product-dialog'),a=displayAvailability(p);
  const selected=Object.fromEntries((p.option_groups||[]).map(g=>[g.id,{}]));
  dialog.innerHTML=`<div class="modal-head"><span class="eyebrow">${demo?'Sample product':'Made just for you'}</span><button class="close-button" aria-label="Close product">×</button></div><div class="modal-content"><div class="product-dialog-layout"><div>${p.photos?.length?`<img id="detail-photo" class="product-dialog-image" src="${safeImage(p.photos[0])}" alt="${esc(p.name)}"><div class="photo-thumbs">${p.photos.map((photo,i)=>`<button data-photo="${i}" aria-label="View photo ${i+1}"><img src="${safeImage(photo)}" alt=""></button>`).join('')}</div>`:placeholder()}<div class="help-card"><strong>Freshly made, with a little notice</strong>${p.lead_days} full production day${p.lead_days===1?'':'s'} required.<br>Earliest available: ${esc(earliestFor(p))}.<br>Minimum order: ${p.min_quantity} unit${p.min_quantity===1?'':'s'}.</div></div><div><h2 id="product-title">${esc(p.name)}</h2>${allowsSameDay(p)?'<div class="notice">Same-day orders are available before our order cutoff, subject to stock and pickup or delivery availability. Every product in your basket must be eligible for same-day orders.</div>':''}${p.pickup_only===true?'<div class="notice">This product is available for pickup only. Orders containing it must be collected from the kitchen.</div>':''}<p class="muted product-description">${esc(p.description)}</p>${insideBox(p,catalog.flavors)}<div class="product-price" id="detail-price">${money(p.price_cents)}</div>${(p.option_groups||[]).map((g,gi)=>`<fieldset class="option-group"><legend>${esc(g.label)} <small class="muted">· Choose ${g.required_count}</small></legend>${g.choices.filter(c=>c.active!==false&&flavorStock(c,state.fulfillment_date,catalog.inventory)>0).map(c=>`<div class="option-choice">${g.required_count===1?`<label><input type="radio" name="group-${gi}" data-group="${esc(g.id)}" data-choice="${esc(c.id)}" value="1"> ${esc(c.label)}</label>`:`<label for="choice-${esc(g.id)}-${esc(c.id)}">${esc(c.label)}</label>`}<span class="option-choice-controls"><small>${c.surcharge_cents?'+'+money(c.surcharge_cents):money(0)}</small>${g.required_count!==1?`<span class="option-stepper"><button type="button" data-option-delta="-1" aria-label="Decrease ${esc(c.label)} quantity" disabled>&minus;</button><input id="choice-${esc(g.id)}-${esc(c.id)}" class="option-count" type="number" inputmode="numeric" min="0" max="${g.required_count}" value="0" step="1" data-group="${esc(g.id)}" data-choice="${esc(c.id)}" aria-label="${esc(c.label)} quantity"><button type="button" data-option-delta="1" aria-label="Increase ${esc(c.label)} quantity">+</button></span>`:''}</span></div>`).join('')}<div class="muted" data-group-count="${esc(g.id)}" aria-live="polite" aria-atomic="true" style="font-size:11px;margin-top:8px">0 of ${g.required_count} selected</div></fieldset>`).join('')}<div class="notice ${a.available?'':'danger'}" style="margin-top:20px">${!a.available||state.fulfillment_date?esc(a.reason):'Choose your fulfillment date in the menu to check availability.'}</div><div id="product-error" role="alert"></div><div class="product-dialog-bottom"><label class="field no-margin" style="width:max-content">Quantity<input id="product-quantity" type="number" min="1" max="999" step="1" value="1"></label><button id="add-to-cart" class="button" ${!a.available||catalog.settings.paused?'disabled':''}>Add to basket · ${money(p.price_cents)}</button></div>${boxDetails(p)}</div></div></div>`;
  dialog.querySelector('.close-button').onclick=()=>dialog.close();dialog.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>$('#detail-photo').src=p.photos[+b.dataset.photo]);
  function refresh(){
    let price=Number(p.price_cents);
    for(const g of p.option_groups||[]){
      const total=Object.values(selected[g.id]).reduce((sum,count)=>sum+count,0);
      const remaining=Math.max(0,g.required_count-total);
      for(const c of g.choices)price+=c.surcharge_cents*Number(selected[g.id][c.id]||0);
      dialog.querySelector('[data-group-count="'+CSS.escape(g.id)+'"]').textContent=
        total+' of '+g.required_count+' selected'+(remaining===0&&g.required_count!==1?' · Reduce a quantity to choose another option.':'');
      dialog.querySelectorAll('.option-count[data-group="'+CSS.escape(g.id)+'"]').forEach(input=>{
        const count=selected[g.id][input.dataset.choice]||0;
        input.max=String(count+remaining);
        input.disabled=remaining===0&&count===0;
        const stepper=input.closest('.option-stepper');
        stepper.querySelector('[data-option-delta="1"]').disabled=remaining===0;
        stepper.querySelector('[data-option-delta="-1"]').disabled=count===0;
      });
    }
    $('#detail-price').textContent=money(price);
    $('#add-to-cart').textContent='Add to basket · '+money(price*Number($('#product-quantity').value||1));
  }
  function updateChoice(input){
    const group=p.option_groups.find(g=>g.id===input.dataset.group),choice=input.dataset.choice;
    if(input.type==='radio')selected[group.id]={[choice]:1};
    else{
      // Count the other flavors so typing, pasting and stepping share the same cap.
      const others=Object.entries(selected[group.id]).reduce((sum,[id,count])=>sum+(id===choice?0:count),0);
      const value=Number(input.value);
      const count=Math.min(Math.max(0,group.required_count-others),Math.max(0,Number.isFinite(value)?Math.trunc(value):0));
      selected[group.id][choice]=count;
      if(input.value!=='')input.value=String(count);
    }
    refresh();
  }
  dialog.querySelectorAll('input[data-group]').forEach(input=>{
    input.oninput=()=>updateChoice(input);
    if(input.type==='number')input.onblur=()=>{input.value=String(selected[input.dataset.group][input.dataset.choice]||0)};
  });
  dialog.querySelectorAll('[data-option-delta]').forEach(button=>button.onclick=()=>{
    const input=button.closest('.option-stepper').querySelector('input');
    input.value=String((selected[input.dataset.group][input.dataset.choice]||0)+Number(button.dataset.optionDelta));
    updateChoice(input);
  });
  $('#product-quantity').oninput=refresh;
  refresh();
  $('#add-to-cart').onclick=()=>{try{const price=selectionPrice(p,selected),quantity=Number($('#product-quantity').value);if(!Number.isInteger(quantity)||quantity<1||quantity>999)throw new Error(`Choose a whole quantity from 1 to 999.`);const same=state.items.find(l=>l.product_id===p.id&&JSON.stringify(l.selections)===JSON.stringify(selected));const nextItems=state.items.map(l=>({...l}));const existing=nextItems.find(l=>l.product_id===p.id&&JSON.stringify(l.selections)===JSON.stringify(selected));if(existing)existing.quantity+=quantity;else nextItems.push({product_id:p.id,name:p.name,quantity,selections:selected,unit_price_cents:price});const stockErrors=basketStockIssues(nextItems,catalog.products,catalog.inventory,state.fulfillment_date);if(stockErrors.length)throw new Error(stockErrors[0]);state.items=nextItems;quote=null;persist();renderCart();dialog.close();toast('Added to your basket.')}catch(e){$('#product-error').className='notice danger';$('#product-error').textContent=e.message}};
  dialog.showModal();
}
function inputField(label,name,value='',type='text',required=true,extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value||'')}" ${required?'required':''} ${extra}></label>`}
function readCheckout(form){const f=new FormData(form);state.buyer={name:String(f.get('buyer_name')||''),email:String(f.get('buyer_email')||''),phone:String(f.get('buyer_phone')||''),social_platform:String(f.get('social_platform')||'').trim(),social_username:String(f.get('social_username')||'').trim()};if(f.has('recipient_name')){state.recipient={name:String(f.get('recipient_name')||''),phone:String(f.get('recipient_phone')||'')};state.address={locality:String(f.get('locality')||''),line1:String(f.get('line1')||''),line2:String(f.get('line2')||''),postal_code:String(f.get('postal_code')||'')};}state.instructions=String(f.get('instructions')||'');state.promo_code=String(f.get('promo_code')||'').trim().toUpperCase();persist()}
function payload(){return {items:state.items.map(({product_id,quantity,selections})=>({product_id,quantity,selections})),fulfillment_date:state.fulfillment_date,method:state.method,buyer:state.buyer,recipient:state.method==='delivery'?state.recipient:null,address:state.method==='delivery'?state.address:null,instructions:state.instructions,promo_code:state.promo_code||null,idempotency_key:state.idempotency_key}}
// Promo checks preview the existing quote; final review always checks again.
function promoContextKey(){
  const p=payload();
  return JSON.stringify({code:p.promo_code,items:p.items,date:p.fulfillment_date,method:p.method,locality:p.address?.locality||'',user:session?.user?.id||'',verified:session?.user?.email_confirmed_at||''});
}
function resetPromoCheck(message=''){
  promoRequest++;promoPending=false;promoQuote=null;promoKey=promoContextKey();
  promoMessage=message||(state.promo_code?'Click Apply code to check your discount.':'');promoTone='';
}
function updatePromoUi(){
  const form=$('#checkout-form');if(!form)return;
  if(promoKey!==promoContextKey())resetPromoCheck();
  const message=$('#promo-status'),apply=$('#apply-promo'),remove=$('#remove-promo');
  message.textContent=promoMessage;message.className=promoMessage?`notice promo-status ${promoTone}`:'promo-status';message.hidden=!promoMessage;
  apply.textContent=promoPending?'Checking…':'Apply code';apply.disabled=busy||promoPending||!state.promo_code;
  apply.setAttribute('aria-busy',String(promoPending));remove.hidden=!state.promo_code;remove.disabled=busy;
  $('#review-order').disabled=busy||promoPending;
  $('#checkout-totals').innerHTML=amountLines(promoQuote);
}
async function applyPromoCode(form){
  if(busy||promoPending||form!==$('#checkout-form'))return;
  readCheckout(form);form.elements.namedItem('promo_code').value=state.promo_code;resetPromoCheck();
  if(!state.promo_code){updatePromoUi();return;}
  if(demo||!configured){promoMessage='Promo codes can be checked in the live shop after setup.';promoTone='danger';updatePromoUi();return;}
  if(!session?.user){promoMessage='Sign in with a verified email address to apply a promo code. Your cart is saved.';promoTone='danger';updatePromoUi();return;}
  const request=++promoRequest,key=promoKey,requestPayload=payload();
  const isCurrent=()=>request===promoRequest&&form.isConnected&&form===$('#checkout-form')&&$('#checkout-dialog').open&&key===promoContextKey();
  promoPending=true;promoMessage='Checking your code…';updatePromoUi();
  try{
    const checked=await api('quote',requestPayload);
    if(!isCurrent())return;
    if(checked?.promo_snapshot?.code!==state.promo_code||!Number.isFinite(checked.discount_cents)||checked.discount_cents<0)throw new Error('This code could not be confirmed. Please try again.');
    promoQuote=checked;promoTone='success';
    promoMessage=checked.discount_cents>0?`${state.promo_code} applied — you saved ${money(checked.discount_cents)}.`:`${state.promo_code} is valid, but gives no discount on this basket.`;
  }catch(error){
    if(isCurrent()){promoQuote=null;promoTone='danger';promoMessage=error.message||'We could not check this code. Please try again.';}
  }finally{
    if(request===promoRequest){promoPending=false;if(form===$('#checkout-form'))updatePromoUi();}
  }
}
