        if(state.promo_code)throw new Error('Promo validation needs the connected backend and a verified account. Leave the sample code field empty.');
        checked={items:state.items.map(l=>({...l,name:lineProduct(l).name,unit_price_cents:linePrice(l),line_total_cents:linePrice(l)*l.quantity,selection_labels:selectionLabels(lineProduct(l),l.selections)})),subtotal_cents:subtotal(),discount_cents:0,delivery_cents:zoneFee(),total_cents:subtotal()+zoneFee(),delivery_zone_name:selectedZone()?.name||'',delivery_zone_description:selectedZone()?.description||''};
